          type="button"
          className="journeyStageHit"
          aria-label={title}
          aria-disabled={locked || activeStage}
          onClick={() => !locked && !activeStage && navigation?.navigate(stage.id)}
        />
        <i>{locked ? <Icon name="lock" /> : access.status === "done" ? "✓" : index + 1}</i>
        <span>{stage.label}</span>
        {index < journeyStages.length - 1 && <em />}
      </article>;
    })}

{progress && <span className="missionProgress" aria-label={`진행 ${progress.now}/${progress.total}`}>
      {Array.from({ length: progress.total }, (_, i) => <i key={i} className={i < progress.now ? "on" : ""} />)}
      <small>{progress.now}/{progress.total}</small>
